#!/usr/bin/env python3
"""
Phase 02c Worker: Process batch with minimal MCP calls
Strategy: Use pattern matching from titles/procedures to search for relevant code
"""
import json
import re
from pathlib import Path

def extract_primary_element(item):
    """Extract the most likely primary code element from checklist item"""
    title = item.get('title', '')

    # Look for specific patterns
    # Pattern 1: "Does <function_name> ..." or "Is <function_name> ..."
    match = re.search(r'(?:Does|Is|Can)\s+([a-z_][a-z0-9_]*)', title, re.IGNORECASE)
    if match:
        return match.group(1).lower()

    # Pattern 2: Function names in snake_case
    snake_case = re.findall(r'\b([a-z][a-z0-9_]{3,})\b', title)
    if snake_case:
        # Prefer longer names
        return max(snake_case, key=len)

    # Pattern 3: Type names in PascalCase
    pascal_case = re.findall(r'\b([A-Z][a-zA-Z0-9]{2,})\b', title)
    if pascal_case:
        return max(pascal_case, key=len)

    return None

def categorize_items(items):
    """Categorize items by type of check"""
    categorized = {
        'function_checks': [],     # Checks about specific functions
        'type_checks': [],         # Checks about type constructors/validators
        'constant_checks': [],     # Checks about constants/limits
        'boundary_checks': [],     # General trust boundary checks
        'spec_only': []           # Specification-level checks with no clear code target
    }

    for item in items:
        title = item.get('title', '').lower()
        primary = extract_primary_element(item)

        if 'eip-' in title or 'specification' in title:
            # Likely specification-level
            if primary and ('_' in primary or primary[0].isupper()):
                # But has a clear code target
                if '_' in primary:
                    categorized['function_checks'].append((item, primary))
                else:
                    categorized['type_checks'].append((item, primary))
            else:
                categorized['spec_only'].append((item, None))
        elif primary:
            if '_' in primary:
                categorized['function_checks'].append((item, primary))
            elif primary[0].isupper():
                categorized['type_checks'].append((item, primary))
            else:
                categorized['boundary_checks'].append((item, primary))
        else:
            categorized['boundary_checks'].append((item, None))

    return categorized

def main():
    queue_file = Path('outputs/02c_ASYNC_QUEUE_W1B10_1771254431.json')

    with open(queue_file) as f:
        data = json.load(f)

    items = data['items'][:100]
    print(f"Categorizing {len(items)} items...")

    categorized = categorize_items(items)

    print("\nCategories:")
    for cat, items_list in categorized.items():
        print(f"  {cat}: {len(items_list)}")
        if items_list and items_list[0][1]:  # Has element
            sample_elements = [elem for _, elem in items_list[:5] if elem]
            print(f"    Sample: {sample_elements}")

    # Save categorization for next step
    output = {
        'function_targets': sorted(set(elem for _, elem in categorized['function_checks'] if elem)),
        'type_targets': sorted(set(elem for _, elem in categorized['type_checks'] if elem)),
        'spec_only_count': len(categorized['spec_only']),
        'boundary_check_count': len(categorized['boundary_checks'])
    }

    with open('temp_categorized.json', 'w') as f:
        json.dump(output, f, indent=2)

    print(f"\nUnique function targets: {len(output['function_targets'])}")
    print(f"Unique type targets: {len(output['type_targets'])}")

if __name__ == '__main__':
    main()

