        'line': 879,
        'symbol': 'DepositRequestsFromConsensus',
        'keywords': ['deposit_requests', 'deposit request', 'parse_deposit_requests']
    },
    'ProcessDeposit': {
        'file': 'beacon-chain/state/state-native/setters_deposits.go',  # Likely location
        'line': 1,
        'symbol': 'ProcessDeposit',
        'keywords': ['extract_deposit_data', 'deposit event', 'deposit data']
    },

    # Validator operations
    'GetValidatorsCustodyRequirement': {
        'file': 'beacon-chain/core/custody',  # Likely path
        'line': 1,
        'symbol': 'GetValidatorsCustodyRequirement',
        'keywords': ['get_validators_custody_requirement', 'custody requirement', 'custody']
    },

    # Fork/Epoch operations
    'ComputeForkVersion': {
        'file': 'beacon-chain/core/helpers/version.go',  # Likely location
        'line': 1,
        'symbol': 'ComputeForkVersion',
        'keywords': ['compute_fork_version', 'fork version']
    },

    # Data column operations
    'GetDataColumnSidecars': {
        'file': 'beacon-chain/core/peerdas',  # Likely path
        'line': 1,
        'symbol': 'GetDataColumnSidecars',
        'keywords': ['get_data_column_sidecars', 'data column', 'sidecar']
    },
}

# Execution layer specifications (not in consensus client)
EXECUTION_LAYER_SPECS = {
    'encode_account', 'rlp', 'trie_get', 'receipt', 'transaction signature',
    'eip-7702', 'authorization', 'requests_hash', 'execution client consensus',
    'sender address recovery', 'ecdsa signature verification'
}

def matches_any_keyword(text, keywords):
    """Check if text matches any of the keywords"""
    text_lower = text.lower()
    return any(kw in text_lower for kw in keywords)

def find_best_match(item):
    """Find the best matching code location for an item"""
    title = item.get('title', '').lower()
    procedure = item.get('test_procedure', '').lower()
    combined = title + ' ' + procedure

    # Check for execution layer specs first
    for spec in EXECUTION_LAYER_SPECS:
        if spec in combined:
            return ('specification_only', 'Execution layer specification - not implemented in consensus client')

    # Try to match with known code locations
    best_match = None
    best_score = 0

    for impl_name, info in CODE_DATABASE.items():
        keywords = info.get('keywords', [])
        score = sum(1 for kw in keywords if kw in combined)

