            best_score = score
            best_match = (impl_name, info)

    if best_score > 0:
        impl_name, info = best_match
        return ('resolved', impl_name, info)

    # Check for generic consensus layer concepts
    consensus_keywords = [
        'deposit', 'validator', 'attestation', 'beacon', 'committee',
        'fork', 'epoch', 'slot', 'custody', 'blob', 'kzg', 'das',
        'data column', 'sidecar', 'peerdas', 'fulu'
    ]

    if any(kw in combined for kw in consensus_keywords):
        return ('not_found', 'Consensus layer concept without specific code match')

    # Default to specification-only
    return ('specification_only', 'General trust boundary check - specification level')

