    """Process all items with comprehensive matching"""
    results = []

    for item in items:
        check_id = item['check_id']
        match_result = find_best_match(item)

        if match_result[0] == 'resolved':
            _, impl_name, info = match_result
            result = {
                'check_id': check_id,
                'code_scope': {
                    'locations': [{
                        'file': info['file'],
                        'symbol': info['symbol'],
                        'line_range': {'start': info['line'], 'end': info['line'] + 50},
                        'role': 'primary'
                    }],
                    'resolution_status': 'resolved',
                    'resolution_note': f'Matched to implementation: {impl_name}'
                },
                'code_excerpt': f'// Location: {info["file"]}:{info["line"]}\n// Function: {impl_name}'
